  "decision": {
    "conditional_optimization": {
      "eligible_only_if": [
        "A separately labeled warm rerun confirms the relevant warm advantage and a separately labeled cold rerun meets a workload-specific SLO set before evaluation, with every censored run reported and explained.",
        "CTRL-A-OWNER-TOKEN-CLEANUP and CTRL-A-STRUCTURED-BIND pass their negative tests.",
        "Named cleanup and recovery owners, a preserved prior state, and a successful rollback rehearsal satisfy CON-OWNER and CON-ROLLBACK."
      ],
      "evidence": [
        "BM-A-WARM",
        "BM-A-COLD",
        "BM-B-WARM",
        "BM-D-WARM",
        "INC-A-CLEANUP",
        "SEC-A-BIND"
      ],
      "option": "A"
    },
    "depends_on": [
      "D-MIGRATION",
      "D-RECOVERY",
      "B-ISOLATION",
      "CON-MIGRATION",
      "CON-OWNER",
      "CON-ROLLBACK"
    ],
    "phases": [
      {
        "gates": [
          {
            "check": "Run the legacy compatibility suite in a timestamped D migration rehearsal and record the start time, end time, and results.",
            "expected": "All legacy compatibility checks pass and the elapsed migration time is no more than 14 days.",
            "gate_id": "G-MIGRATION-14D"
          },
          {
            "check": "Record named cleanup and recovery owners, run the D recovery runbook, and record the approved recovery objectives and observed results.",
            "expected": "Both owners accept responsibility and the rehearsal meets the approved recovery objectives before D handles production work.",
            "gate_id": "G-D-RECOVERY"
          },
          {
            "check": "Snapshot the prior legacy state and execute a rehearsal rollback from D using the declared trigger.",
            "expected": "The preserved legacy state is restored and its compatibility suite passes.",
            "gate_id": "G-D-ROLLBACK"
          }
        ],
        "option": "D",
        "owner": "Migration Lead",
        "phase": 1,
        "purpose": "Provide the legacy-compatible bridge within 14 days while preserving a tested return to the prior legacy state.",
        "rollback_triggers": [
          {
            "action": "Stop D rollout and restore the preserved legacy state.",
            "check": "Review timestamped migration progress and legacy compatibility results at each rollout checkpoint.",
            "condition": "The migration exceeds or is forecast to exceed 14 days, or any required legacy compatibility check fails.",
            "trigger_id": "RT-D-DEADLINE-OR-COMPAT"
          },
          {
            "action": "Pause D expansion, restore the preserved legacy state when recovery is required, and assign the incident to the Fabric Recovery owner.",
            "check": "Verify owner assignment and the D recovery-runbook result before each expansion step and after every recovery incident.",
            "condition": "The recovery owner is absent, the runbook rehearsal fails its approved objectives, or recovery is delayed in operation.",
            "trigger_id": "RT-D-RECOVERY"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "Run automated negative-access tests against B mounts and credentials, including attempts to mount outside the workspace and use credentials beyond their declared scope.",
            "expected": "Only workspace mounts are present and every out-of-scope mount or credential operation is denied.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Complete a provider qualification record covering identity and revocation, quotas, availability, retention, and recovery behavior, then execute the documented recovery test.",
            "expected": "Each provider boundary has an accepted owner and criterion, and the recovery test passes those criteria.",
            "gate_id": "G-B-PROVIDER"
          },
          {
            "check": "Rerun B warm and cold workloads separately in the cutover environment, retaining sample counts, censored counts, invalid-run reasons, and workload-specific results.",
            "expected": "Both distributions are valid, every censored or invalid run is accounted for, and each meets its workload-specific SLO approved before the run.",
            "gate_id": "G-B-BENCHMARK"
          },
          {
            "check": "Verify written acceptance by the named cleanup owner and recovery owner immediately before B cutover.",
            "expected": "Both owners are named, reachable, and have accepted their runbooks and escalation duties.",
            "gate_id": "G-B-OWNER"
          },
          {
            "check": "Preserve the last known-good D state and execute a B-to-D rollback rehearsal using each declared phase-2 trigger.",
            "expected": "D is restored, its compatibility suite passes, and rollback evidence is retained before B cutover.",
            "gate_id": "G-B-ROLLBACK"
          }
        ],
        "option": "B",
        "owner": "Execution Platform Lead",
        "phase": 2,
        "purpose": "Cut over from D to B only after isolation, provider, benchmark, ownership, recovery, and rollback gates close the supplied evidence boundaries.",
        "rollback_triggers": [
          {
            "action": "Revoke affected credentials, stop B admission, and restore the preserved D state.",
            "check": "Continuously evaluate mount inventory, credential-scope denials, and isolation alerts.",
            "condition": "Any mount escapes the workspace boundary or any credential succeeds outside its declared scope.",
            "trigger_id": "RT-B-ISOLATION"
          },
          {
            "action": "Stop B expansion and restore the preserved D state until the workload distribution is rerun and accepted.",
            "check": "Evaluate warm and cold SLOs separately and account for every censored and invalid run during canary rollout.",
            "condition": "Either workload-specific SLO is breached, a run is pooled across workloads, or censoring or invalid runs are unexplained.",
            "trigger_id": "RT-B-BENCHMARK"
          },
          {
            "action": "Stop B admission, invoke the named recovery owner, and restore D if the approved recovery criteria cannot be met.",
            "check": "Verify provider qualification assumptions and recovery-runbook results at cutover and after provider or identity changes.",
            "condition": "A provider assumption becomes false, the recovery owner is unavailable, or the recovery test fails an approved criterion.",
            "trigger_id": "RT-B-PROVIDER-RECOVERY"
          }
        ]
      }
    ],
    "strategy": "Use D as a legacy-compatible migration bridge within 14 days, then cut over to B only after isolation, provider, benchmark, ownership, recovery, and rollback gates pass; retain A solely as a gated workload-specific optimization and reject C's invalid pooled claim."
  },
